                    reader.Reset(FullValueOracle.Source(bytes), projection);
                else
                    reader.Reset(new MemoryStream(bytes, writable: false), projection);
            }
            var index = 0;
            while (reader.MoveNext())
            {
                if (index >= rows.Length)
                    throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} returned an extra row {index}.");
                var diff = Compare(reader.Current, (Rnd322v)rows[index], mask);
                if (diff is not null)
                    throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} lost '{diff}' at row {index} (mask {mask:x}).");
                index++;
            }
            if (index != rows.Length)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} read {index} rows; expected {rows.Length}.");
        }
    }

    public override void CheckEvolved(byte[] bytes, object?[][] expected, int mask, ParquetSchemaEvolutionOptions? evolution, RowReaderOptions options)
    {
        using var reader = Rnd322v.CreateRowReader(new MemoryStream(bytes, writable: false), Project(mask), options, evolution);
        var index = 0;
        while (reader.MoveNext())
        {
            if (index >= expected.Length)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} evolved read returned an extra row {index}.");
            var diff = CompareEvolved(reader.Current, expected[index], mask);
            if (diff is not null)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} evolved read lost '{diff}' ({Clr[Array.IndexOf(Props, diff)]}) at row {index} (mask {mask:x}); expected {DeepEq.Describe(expected[index][Array.IndexOf(Props, diff)])}.");
            index++;
        }
        if (index != expected.Length)
            throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} evolved read returned {index} of {expected.Length} rows.");
    }

    public override List<int> ReadSeqs(byte[] bytes, object[] rows, RowReaderOptions options)
    {
        var seqs = new List<int>();
        using var reader = Rnd322v.CreateRowReader(new MemoryStream(bytes, writable: false), default, options);
        while (reader.MoveNext())
        {
            var seq = reader.Current.Seq;
            if ((uint)seq >= (uint)rows.Length)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} dataset file returned unknown Seq {seq}.");
            var diff = Compare(reader.Current, (Rnd322v)rows[seq], 255);
            if (diff is not null)
                throw new PlankRowApiFuzzTarget.RowApiRoundTripException($"{Name} dataset lost '{diff}' of row {seq}.");
            seqs.Add(seq);
        }
        return seqs;
    }

    public override IRandomDatasetSink CreateDataset(Func<object, int> partitionOf, bool ownedPath, bool createParts, FaultingDatasetFile[] files, DatasetWriterOptions options)
    {
        Rnd322v.Route route = (Rnd322v row, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.Select(partitionOf(row), ownedPath, pool, out allocation);
        DatasetFilePath filePath = (ReadOnlySpan<byte> key, ulong index, IParquetBufferPool pool, out ParquetBuffer? allocation) =>
            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd322v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd322v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd322v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd322v)row);
        public void Dispose() => writer.Dispose();
    }
}